package matteroverdrive.block;
import matteroverdrive.blockentity.TransporterBlockEntity;
import matteroverdrive.registry.ModBlockEntities;
import net.minecraft.core.BlockPos;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.InteractionHand;import net.minecraft.world.InteractionResult;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.BaseEntityBlock;import net.minecraft.world.level.block.RenderShape;import net.minecraft.world.level.block.entity.BlockEntity;import net.minecraft.world.level.block.entity.BlockEntityTicker;import net.minecraft.world.level.block.entity.BlockEntityType;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.BlockHitResult;import net.minecraftforge.network.NetworkHooks;import javax.annotation.Nullable;
public class TransporterBlock extends BaseEntityBlock{
 public TransporterBlock(Properties p){super(p);}@Override public RenderShape getRenderShape(BlockState s){return RenderShape.MODEL;}@Nullable @Override public BlockEntity newBlockEntity(BlockPos p,BlockState s){return new TransporterBlockEntity(p,s);}@Nullable @Override public <T extends BlockEntity> BlockEntityTicker<T> getTicker(Level l,BlockState s,BlockEntityType<T> t){if(l.isClientSide||t!=ModBlockEntities.TRANSPORTER.get())return null;return (a,b,c,e)->TransporterBlockEntity.serverTick(a,b,c,(TransporterBlockEntity)e);}@Override public InteractionResult use(BlockState s,Level l,BlockPos p,Player pl,InteractionHand h,BlockHitResult hit){if(!l.isClientSide&&pl instanceof ServerPlayer sp&&l.getBlockEntity(p) instanceof TransporterBlockEntity t)NetworkHooks.openScreen(sp,t,p);return InteractionResult.sidedSuccess(l.isClientSide);}@Override public void onRemove(BlockState o,Level l,BlockPos p,BlockState n,boolean m){if(!o.is(n.getBlock())&&l.getBlockEntity(p) instanceof TransporterBlockEntity t)t.dropContents();super.onRemove(o,l,p,n,m);}
}